-- Read-only catalog export for an isolated test stack. No clinic data or secrets.
-- The JSON is ordered for restore with check_function_bodies disabled, as in pg_dump.
with app_relations as (
  select c.*, n.nspname, format('%I.%I', n.nspname, c.relname) as qualified
  from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname in ('public','private') and c.relkind in ('r','v','S')
), sections as (
  select 0 as position, 'schemas' as name,
    'create schema if not exists private; create schema if not exists extensions; set check_function_bodies = off; set search_path = public, extensions;' as sql
  union all
  select 1, 'extensions', string_agg(format('create extension if not exists %I with schema %I;', e.extname,n.nspname), E'\n' order by e.extname)
  from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname in ('pgcrypto','uuid-ossp','vector','btree_gist','pg_cron','pg_net','supabase_vault')
  union all
  select 2, 'enums', string_agg(ddl,E'\n' order by ddl) from (
    select format('create type %I.%I as enum (%s);',n.nspname,t.typname,string_agg(quote_literal(e.enumlabel),', ' order by e.enumsortorder)) as ddl
    from pg_type t join pg_namespace n on n.oid=t.typnamespace join pg_enum e on e.enumtypid=t.oid where n.nspname in ('public','private') group by n.nspname,t.typname
  ) enums
  union all
  select 3, 'sequences', string_agg(format('create sequence %s as %s increment by %s minvalue %s maxvalue %s start with %s cache %s %s;',c.qualified,format_type(s.seqtypid,null),s.seqincrement,s.seqmin,s.seqmax,s.seqstart,s.seqcache,case when s.seqcycle then 'cycle' else 'no cycle' end),E'\n' order by c.qualified)
  from app_relations c join pg_sequence s on s.seqrelid=c.oid where not exists(select 1 from pg_depend d where d.objid=c.oid and d.deptype='i')
  union all
  select 4, 'tables', string_agg(ddl,E'\n' order by ddl) from (
    select format('create table %s (%s);',c.qualified,string_agg(format('%I %s%s%s',a.attname,format_type(a.atttypid,a.atttypmod),case when a.attgenerated<>'' then ' generated always as ('||pg_get_expr(d.adbin,d.adrelid)||') stored' when a.attidentity='a' then ' generated always as identity' when a.attidentity='d' then ' generated by default as identity' else '' end,case when a.attnotnull then ' not null' else '' end),', ' order by a.attnum)) as ddl
    from app_relations c join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where c.relkind='r' group by c.qualified
  ) tables
  union all
  select 5, 'views', string_agg(format('create view %s %s as %s;',c.qualified,case when c.reloptions is null then '' else 'with ('||array_to_string(c.reloptions,', ')||')' end,trim(trailing ';' from pg_get_viewdef(c.oid,true))),E'\n' order by c.qualified)
  from app_relations c where c.relkind='v'
  union all
  select 6, 'functions', string_agg(pg_get_functiondef(p.oid)||';',E'\n' order by p.oid)
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prokind='f'
  union all
  select 7, 'defaults', string_agg(format('alter table %s alter column %I set default %s;',c.qualified,a.attname,pg_get_expr(d.adbin,d.adrelid)),E'\n' order by c.qualified,a.attnum)
  from app_relations c join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where c.relkind='r' and a.attgenerated=''
  union all
  select 8, 'constraints', string_agg(format('alter table %s add constraint %I %s;',c.qualified,k.conname,pg_get_constraintdef(k.oid,true)),E'\n' order by (k.contype='f'),c.qualified,k.conname)
  from app_relations c join pg_constraint k on k.conrelid=c.oid where c.relkind='r'
  union all
  select 9, 'indexes', string_agg(pg_get_indexdef(i.indexrelid)||';',E'\n' order by i.indexrelid)
  from app_relations c join pg_index i on i.indrelid=c.oid where not exists(select 1 from pg_constraint k where k.conindid=i.indexrelid)
  union all
  select 10, 'triggers', string_agg(pg_get_triggerdef(t.oid,true)||';',E'\n' order by t.oid)
  from app_relations c join pg_trigger t on t.tgrelid=c.oid where not t.tgisinternal
  union all
  select 11, 'rls', string_agg(format('alter table %s %s row level security; %s',c.qualified,case when c.relrowsecurity then 'enable' else 'disable' end,case when c.relforcerowsecurity then format('alter table %s force row level security;',c.qualified) else '' end),E'\n' order by c.qualified)
  from app_relations c where c.relkind='r'
  union all
  select 12, 'policies', string_agg(format('create policy %I on %I.%I as %s for %s to %s%s%s;',policyname,schemaname,tablename,permissive,cmd,array_to_string(array(select quote_ident(role_name) from unnest(roles) role_name),', '),case when qual is null then '' else ' using ('||qual||')' end,case when with_check is null then '' else ' with check ('||with_check||')' end),E'\n' order by schemaname,tablename,policyname)
  from pg_policies where schemaname in ('public','private')
  union all
  select 13, 'schema_grants', string_agg(format('revoke all on schema %I from public, anon, authenticated, service_role;%s',n.nspname,coalesce((select string_agg(format('grant %s on schema %I to %s;',a.privilege_type,n.nspname,case when a.grantee=0 then 'public' else quote_ident(pg_get_userbyid(a.grantee)) end),E'\n') from aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a where a.grantee=0 or pg_get_userbyid(a.grantee) in ('anon','authenticated','service_role')),'')),E'\n')
  from pg_namespace n where n.nspname in ('public','private')
  union all
  select 14, 'relation_grants', string_agg(format('revoke all on %s %s from public, anon, authenticated, service_role;%s',case when c.relkind='S' then 'sequence' else 'table' end,c.qualified,coalesce((select string_agg(format('grant %s on %s %s to %s%s;',a.privilege_type,case when c.relkind='S' then 'sequence' else 'table' end,c.qualified,case when a.grantee=0 then 'public' else quote_ident(pg_get_userbyid(a.grantee)) end,case when a.is_grantable then ' with grant option' else '' end),E'\n') from aclexplode(coalesce(c.relacl,acldefault(case when c.relkind='S' then 's'::"char" else 'r'::"char" end,c.relowner))) a where a.grantee=0 or pg_get_userbyid(a.grantee) in ('anon','authenticated','service_role')),'')),E'\n' order by c.qualified)
  from app_relations c
  union all
  select 15, 'function_grants', string_agg(format('revoke all on function %I.%I(%s) from public, anon, authenticated, service_role;%s',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),coalesce((select string_agg(format('grant execute on function %I.%I(%s) to %s;',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),case when a.grantee=0 then 'public' else quote_ident(pg_get_userbyid(a.grantee)) end),E'\n') from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantee=0 or pg_get_userbyid(a.grantee) in ('anon','authenticated','service_role')),'')),E'\n' order by p.oid)
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prokind='f'
)
select name, sql from sections where sql is not null order by position;
